import json,subprocess
from pathlib import Path
code=r'''
import fs from 'node:fs';import {gunzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {DatabaseSync} from 'node:sqlite';import {ForumState} from './src/forumFlow/state.mjs';import {ForumRuntime} from './src/forumFlow/runtime.mjs';
const root='/var/lib/forum-flow/stability-20261123',require=createRequire('/opt/forum-flow/current/package.json'),env=require('dotenv').parse(fs.readFileSync('/etc/forum-flow/forum.env')),ES=require('elasticsearch'),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:30000}),db=new DatabaseSync('/var/lib/forum-flow/runtime/state.sqlite',{readOnly:true}),backup=fs.readdirSync('/var/backups/forum-flow').filter(s=>s.startsWith('stability-20261123-')).sort().at(-1),old=new DatabaseSync('/var/backups/forum-flow/'+backup+'/state.sqlite',{readOnly:true}),cohort=old.prepare("SELECT site,role,native_id,thread_id FROM forum_documents WHERE export_state='held'").all(),apply=JSON.parse(fs.readFileSync(root+'/forum-apply.json')),sites=JSON.parse(fs.readFileSync('config/forum-flow/sites.json')),r={at:new Date().toISOString(),cohort:cohort.length,rows:[],parentControls:[],counts:{},nativeGuardReplay:null};
try{const info=await es.info(),proof=JSON.parse(fs.readFileSync('/etc/forum-flow/identity-proof.json'));if(!proof.verified||!info.version.number.startsWith('5.6.')||createHash('sha256').update(info.cluster_uuid).digest('hex')!==proof.clusterFingerprint)throw Error('QC_ES_IDENTITY_CHANGED');r.clusterFingerprintVerified=true;r.esHealth=await es.cluster.health({timeout:'5s'});
 const work=[];for(const key of cohort){const row=db.prepare('SELECT * FROM forum_documents WHERE site=? AND role=? AND native_id=?').get(key.site,key.role,key.native_id),binding=db.prepare('SELECT * FROM forum_es_bindings WHERE site=? AND role=? AND native_id=?').get(key.site,key.role,key.role==='forumTopic'?key.thread_id:key.native_id);r.counts[row.export_state]=(r.counts[row.export_state]||0)+1;if(!binding||!['created','existing'].includes(row.export_state)){r.rows.push({...key,state:row.export_state,reason:row.export_reason,verified:false});continue;}work.push({row,binding,doc:JSON.parse(row.doc),parent:apply.parents.find(p=>p.site===row.site&&p.threadId===row.thread_id)});}
 for(let i=0;i<work.length;i+=150){const batch=work.slice(i,i+150),hits=await es.mget({body:{docs:batch.map(({row,binding})=>({_index:binding.es_index,_type:row.role,_id:binding.es_id}))}});for(let j=0;j<batch.length;j++){const {row,binding,doc,parent}=batch[j],hit=hits.docs[j],source=hit._source,o={site:row.site,role:row.role,nativeId:row.native_id,threadId:row.thread_id,state:row.export_state,id:binding.es_id,found:hit.found===true};if(source){o.publishedDateMatches=source.publishedDate===binding.published;o.nativePublicationMatches=row.role==='forumTopic'?source.publishedDate===binding.published:Date.parse(source.publishedDate)===Date.parse(doc._source.publishedDate);o.bodyMatches=row.role==='forumTopic'&&row.export_state==='existing'?null:source.content===doc._source.content;if(row.role==='forumComment'){const pb=db.prepare("SELECT * FROM forum_es_bindings WHERE site=? AND role='forumTopic' AND es_id=?").get(row.site,parent?.id);o.parentMatches=!!pb&&source.parentId===parent.id&&source.parentDate===pb.published;}else o.parentMatches=true;o.verified=o.publishedDateMatches&&o.nativePublicationMatches&&o.parentMatches&&o.bodyMatches!==false;}else o.verified=false;r.rows.push(o);}}
 for(const p of apply.parents){const hit=await es.get({index:p.index,type:'forumTopic',id:p.id});r.parentControls.push({site:p.site,threadId:p.threadId,sourceUnchanged:createHash('sha256').update(JSON.stringify(hit._source)).digest('hex')===p.sourceHash,versionUnchanged:hit._version===p.version});}
 const probe=JSON.parse(fs.readFileSync(root+'/forum-error-probe.json')),bad=probe.rows.find(p=>p.reason.includes('NOT NULL'));if(bad){const memory=await ForumState.open(':memory:');try{const site=sites.find(s=>s.domain===bad.site),runtime=new ForumRuntime({state:memory,sites:[site],transport:{close:async()=>{}}});memory.enqueue(site.domain,bad.url,bad.native_id);const row=memory.ready(site.domain,1)[0];runtime.fetch=async()=>({html:gunzipSync(fs.readFileSync(bad.file)).toString(),finalUrl:bad.finalUrl});await runtime.topic(site,row);const after=memory.db.prepare('SELECT processed,reason FROM forum_urls').get();r.nativeGuardReplay={...after,savedDocuments:memory.db.prepare('SELECT count(*) n FROM forum_documents').get().n,verified:after.processed===0&&after.reason==='ROOT_THREAD_IDENTITY_UNCONFIRMED'&&memory.db.prepare('SELECT count(*) n FROM forum_documents').get().n===0};}finally{memory.close();}}
 r.verified=r.cohort===1198&&r.rows.every(p=>p.verified)&&r.parentControls.every(p=>p.sourceUnchanged)&&r.nativeGuardReplay?.verified;fs.writeFileSync(root+'/forum-es-readback.json',JSON.stringify(r,null,2));console.log(JSON.stringify(r));
}finally{db.close();old.close();es.close();}
'''
p=subprocess.run(['/opt/forum-flow/node/bin/node','--input-type=module','-e',code],cwd='/opt/forum-flow/current',capture_output=True,text=True,timeout=240);print(p.stdout)
if p.returncode:raise RuntimeError('FORUM_STABILITY_READBACK_FAILED')
